  INSERT INTO public.users(id,display_name,initial) VALUES ('recap-demo-an','Minh An · mẫu','MA'),
    ('recap-demo-binh','Ngọc Bình · mẫu','NB'),
    ('recap-demo-chau','Linh Châu · mẫu','LC') ON CONFLICT DO NOTHING;
  INSERT INTO public.ideas(id,title,description,category,tags,search_text,creator_id,created_at) VALUES ('demo-ai-recap','Data Crawling Lab · Thảo luận mẫu','Cuộc thảo luận mẫu về crawler sách, chất lượng dữ liệu và kế hoạch demo. Dữ liệu hư cấu để xem thử AI daily và weekly recap.','Công nghệ',ARRAY['Công nghệ','Data crawling','Python','PostgreSQL','Demo','AI recap'],'data crawling lab thao luan mau python postgresql demo ai recap','recap-demo-an','2026-10-09T08:50:00+07:00');
  INSERT INTO public.memberships(idea_id,user_id) VALUES ('demo-ai-recap','recap-demo-an'),('demo-ai-recap','recap-demo-binh'),('demo-ai-recap','recap-demo-chau');
  INSERT INTO public.comments(id,idea_id,parent_id,author_id,body,created_at) VALUES
    ('recap-demo-01','demo-ai-recap',NULL,'recap-demo-an','Mình muốn làm Data Crawling Lab để so sánh cách crawl trang tĩnh, trang động và dữ liệu giao thông. Bản đầu nên chọn phạm vi nào để có demo chạy được trong hai tuần?','2026-10-09T09:00:00+07:00'),
    ('recap-demo-02','demo-ai-recap','recap-demo-01','recap-demo-binh','Mình đề xuất bắt đầu bằng sản phẩm sách trên books.toscrape.com. Có tiêu đề, giá và phân trang khá rõ. Dữ liệu giao thông dùng bộ CSV công khai ở giai đoạn sau để tránh ôm quá nhiều nguồn.','2026-10-09T09:05:00+07:00'),
    ('recap-demo-03','demo-ai-recap','recap-demo-01','recap-demo-chau','Mình đồng ý chọn website dành cho luyện scraping. Cần kiểm tra robots.txt, giữ tốc độ thấp và không crawl khu vực cần đăng nhập. Demo nên ghi rõ nguồn và thời điểm thu thập.','2026-10-09T09:10:00+07:00'),
    ('recap-demo-04','demo-ai-recap','recap-demo-02','recap-demo-an','Chốt MVP lấy sách từ books.toscrape.com, chưa đưa giao thông vào bản đầu. Chúng ta dùng nguồn demo công khai, kiểm tra robots.txt và không truy cập nội dung đăng nhập.','2026-10-09T09:15:00+07:00'),
    ('recap-demo-05','demo-ai-recap','recap-demo-04','recap-demo-binh','Mình sẽ phác thảo schema gồm source_url, title, price, currency và collected_at. Cần lưu URL gốc để chống trùng và kiểm tra lại từng bản ghi.','2026-10-09T09:20:00+07:00'),
    ('recap-demo-06','demo-ai-recap',NULL,'recap-demo-an','Về kiến trúc, nguồn sách là HTML tĩnh. Chúng ta dùng requests + BeautifulSoup hay dùng trình duyệt luôn? Muốn demo được khác biệt mà vẫn đơn giản.','2026-10-11T10:00:00+07:00'),
    ('recap-demo-07','demo-ai-recap','recap-demo-06','recap-demo-binh','Trang tĩnh dùng requests + BeautifulSoup là đủ. Mình đề xuất timeout 10 giây, thử lại tối đa 3 lần với backoff, giãn ít nhất 2 giây giữa request; chưa cần chạy nhiều worker.','2026-10-11T10:05:00+07:00'),
    ('recap-demo-08','demo-ai-recap','recap-demo-06','recap-demo-chau','Trang động có thể dùng Playwright trên một trang demo riêng để so sánh, không cần đưa nó vào pipeline sách. Kafka có cần ngay không hay chỉ lưu PostgreSQL trước?','2026-10-11T10:10:00+07:00'),
    ('recap-demo-09','demo-ai-recap','recap-demo-08','recap-demo-an','Chốt requests + BeautifulSoup cho pipeline sách; Playwright chỉ để minh họa trang động riêng. MVP lưu PostgreSQL và chưa dùng Kafka. Dùng timeout 10 giây, tối đa 3 lần thử có backoff và giãn request ít nhất 2 giây như Bình đề xuất.','2026-10-11T10:15:00+07:00'),
    ('recap-demo-10','demo-ai-recap','recap-demo-09','recap-demo-binh','Mình nhận viết parser và bước kiểm tra dữ liệu: URL không trùng, title không rỗng, price hợp lệ. Mình sẽ ghi các trường hợp lỗi vào tài liệu để Châu làm QA.','2026-10-11T10:20:00+07:00'),
    ('recap-demo-11','demo-ai-recap',NULL,'recap-demo-an','Bản chạy thử đã lấy được 20 sách và lưu URL nguồn. Số bản ghi trùng URL bằng 0. Mình muốn chốt quy ước giá và thời gian trước khi làm dashboard nhỏ.','2026-10-15T09:00:00+07:00'),
    ('recap-demo-12','demo-ai-recap','recap-demo-11','recap-demo-chau','Mình thấy giá có ký hiệu £. Nếu bỏ ký hiệu mà không lưu currency sẽ dễ hiểu sai. Giá nên dùng decimal; collected_at nên lưu UTC rồi đổi múi giờ lúc hiển thị.','2026-10-15T09:05:00+07:00'),
    ('recap-demo-13','demo-ai-recap','recap-demo-12','recap-demo-an','Đồng ý, chốt currency là GBP cho nguồn sách này, price dùng numeric thay vì float và collected_at lưu UTC. Dashboard hiển thị giờ Việt Nam.','2026-10-15T09:10:00+07:00'),
    ('recap-demo-14','demo-ai-recap','recap-demo-11','recap-demo-binh','Mình sẽ sửa parser theo quy ước đó. Phân trang sẽ dừng khi không còn nút next; cần xác minh thêm trường hợp trang cuối trả rỗng để tránh vòng lặp.','2026-10-15T09:15:00+07:00'),
    ('recap-demo-15','demo-ai-recap','recap-demo-12','recap-demo-chau','Mình đã thêm các ca QA cho giá có ký hiệu tiền, trang rỗng và URL lặp. Giá numeric cùng currency riêng đọc rõ hơn. Ca trang cuối vẫn cần chạy thử với parser mới.','2026-10-16T10:00:00+07:00'),
    ('recap-demo-16','demo-ai-recap','recap-demo-13','recap-demo-binh','Parser đã lưu price dạng numeric, currency GBP và collected_at UTC. Mình sẽ hoàn thiện phần README cách chạy, cấu hình delay và kiểm tra trùng URL.','2026-10-16T10:05:00+07:00'),
    ('recap-demo-17','demo-ai-recap',NULL,'recap-demo-an','Chốt demo dùng 20 sách, lưu PostgreSQL và hiển thị 3 chỉ số: số bản ghi, URL trùng, trường dữ liệu thiếu. Xuất CSV mới là đề xuất nếu còn thời gian, chưa đưa vào phạm vi bắt buộc. Câu hỏi còn lại là parser có dừng đúng ở trang cuối hay không.','2026-10-16T10:10:00+07:00'),
    ('recap-demo-18','demo-ai-recap','recap-demo-17','recap-demo-chau','Mình nhận QA dashboard và kiểm tra điều kiện dừng phân trang. Bình làm README parser như đã nói; An nhận slide tổng quan cho buổi demo thứ Hai 19/10. Mình sẽ báo kết quả QA trước buổi demo.','2026-10-16T10:15:00+07:00');
  INSERT INTO ideahub_private.recaps(id,idea_id,kind,period_start,period_end,status,source,content,source_count,created_at,updated_at) VALUES
    ('recap-demo-daily-09','demo-ai-recap','daily','2026-10-09','2026-10-10','ready','sample','{"keyIdeas": [{"text": "MVP bắt đầu bằng dữ liệu sách từ books.toscrape.com; hướng giao thông được để lại cho giai đoạn sau.", "commentIds": ["recap-demo-01", "recap-demo-02", "recap-demo-04"]}, {"text": "Schema dự kiến giữ URL nguồn, tiêu đề, giá, tiền tệ và thời điểm thu thập để chống trùng và truy vết.", "commentIds": ["recap-demo-05"]}], "decisions": [{"text": "Chốt phạm vi bản đầu là nguồn sách demo công khai, kiểm tra robots.txt và không thu thập khu vực cần đăng nhập.", "commentIds": ["recap-demo-03", "recap-demo-04"]}], "nextSteps": [{"text": "Bình phác thảo schema và cách kiểm tra trùng theo URL nguồn.", "commentIds": ["recap-demo-05"]}], "openQuestions": [{"text": "Chưa chốt công cụ và kiến trúc crawler cho các loại trang.", "commentIds": ["recap-demo-01"]}]}'::jsonb,5,'2026-10-10T01:00:00+07:00','2026-10-10T01:00:00+07:00'),
    ('recap-demo-daily-11','demo-ai-recap','daily','2026-10-11','2026-10-12','ready','sample','{"keyIdeas": [{"text": "Tách pipeline sách tĩnh khỏi phần minh họa trang động để demo rõ khác biệt mà vẫn gọn.", "commentIds": ["recap-demo-06", "recap-demo-08", "recap-demo-09"]}], "decisions": [{"text": "Dùng requests + BeautifulSoup cho sách; Playwright chỉ phục vụ minh họa trang động riêng.", "commentIds": ["recap-demo-09"]}, {"text": "MVP lưu PostgreSQL, chưa dùng Kafka; timeout 10 giây, tối đa 3 lần thử có backoff và giãn request ít nhất 2 giây.", "commentIds": ["recap-demo-07", "recap-demo-09"]}], "nextSteps": [{"text": "Bình viết parser và kiểm tra URL trùng, tiêu đề rỗng, giá không hợp lệ; ghi các ca lỗi để Châu làm QA.", "commentIds": ["recap-demo-10"]}], "openQuestions": []}'::jsonb,5,'2026-10-12T01:00:00+07:00','2026-10-12T01:00:00+07:00'),
    ('recap-demo-weekly-05','demo-ai-recap','weekly','2026-10-05','2026-10-12','ready','sample','{"keyIdeas": [{"text": "Thu hẹp Data Crawling Lab về một pipeline sách chạy được; phần giao thông và xử lý phân tán được để lại sau.", "commentIds": ["recap-demo-01", "recap-demo-02", "recap-demo-04", "recap-demo-09"]}, {"text": "Giữ khác biệt giữa trang tĩnh và trang động trong demo, nhưng không dùng trình duyệt cho toàn bộ pipeline.", "commentIds": ["recap-demo-06", "recap-demo-08", "recap-demo-09"]}], "decisions": [{"text": "MVP thu thập sách từ books.toscrape.com, tuân thủ robots.txt và không truy cập nội dung đăng nhập.", "commentIds": ["recap-demo-03", "recap-demo-04"]}, {"text": "Chốt requests + BeautifulSoup cho nguồn tĩnh; Playwright là minh họa riêng; PostgreSQL lưu dữ liệu, chưa dùng Kafka.", "commentIds": ["recap-demo-09"]}, {"text": "Cấu hình request: timeout 10 giây, tối đa 3 lần thử có backoff, giãn ít nhất 2 giây.", "commentIds": ["recap-demo-07", "recap-demo-09"]}], "nextSteps": [{"text": "Bình thiết kế schema có URL nguồn, tiêu đề, giá, tiền tệ và thời điểm thu thập, đồng thời triển khai parser.", "commentIds": ["recap-demo-05", "recap-demo-10"]}, {"text": "Chuẩn bị QA cho URL trùng, tiêu đề rỗng và giá lỗi dựa trên tài liệu parser.", "commentIds": ["recap-demo-10"]}], "openQuestions": []}'::jsonb,10,'2026-10-12T01:00:00+07:00','2026-10-12T01:00:00+07:00'),
    ('recap-demo-daily-15','demo-ai-recap','daily','2026-10-15','2026-10-16','ready','sample','{"keyIdeas": [{"text": "Lượt chạy thử có 20 sách, mỗi bản ghi có URL nguồn và chưa phát hiện URL trùng.", "commentIds": ["recap-demo-11"]}, {"text": "Cần giữ đơn vị tiền tệ và dùng kiểu số chính xác để tránh hiểu sai giá.", "commentIds": ["recap-demo-12", "recap-demo-13"]}], "decisions": [{"text": "Chốt currency GBP, price dùng numeric và collected_at lưu UTC; dashboard đổi sang giờ Việt Nam khi hiển thị.", "commentIds": ["recap-demo-13"]}], "nextSteps": [{"text": "Bình cập nhật parser theo quy ước giá, tiền tệ và thời gian đã thống nhất.", "commentIds": ["recap-demo-14"]}], "openQuestions": [{"text": "Cần xác minh điều kiện dừng ở trang cuối hoặc trang rỗng để crawler không lặp vô hạn.", "commentIds": ["recap-demo-14"]}]}'::jsonb,4,'2026-10-16T01:00:00+07:00','2026-10-16T01:00:00+07:00'),
    ('recap-demo-daily-16','demo-ai-recap','daily','2026-10-16','2026-10-17','ready','sample','{"keyIdeas": [{"text": "Parser đã lưu giá numeric, tiền tệ GBP và thời gian UTC; QA đã bổ sung ca giá có ký hiệu, trang rỗng và URL lặp.", "commentIds": ["recap-demo-15", "recap-demo-16"]}, {"text": "Demo tập trung vào một tập dữ liệu nhỏ có thể kiểm tra chất lượng rõ ràng.", "commentIds": ["recap-demo-17"]}], "decisions": [{"text": "Chốt demo 20 sách trên PostgreSQL với 3 chỉ số: số bản ghi, URL trùng và trường dữ liệu thiếu.", "commentIds": ["recap-demo-17"]}, {"text": "Xuất CSV chưa thuộc phạm vi bắt buộc; mới là đề xuất nếu còn thời gian.", "commentIds": ["recap-demo-17"]}], "nextSteps": [{"text": "Châu QA dashboard và điều kiện dừng phân trang trước buổi demo; Bình hoàn thiện README parser, delay và chống trùng.", "commentIds": ["recap-demo-16", "recap-demo-18"]}, {"text": "An chuẩn bị slide tổng quan cho buổi demo thứ Hai 19/10.", "commentIds": ["recap-demo-18"]}], "openQuestions": [{"text": "Chưa xác nhận parser dừng đúng ở trang cuối; cần chạy QA trước khi kết luận.", "commentIds": ["recap-demo-15", "recap-demo-17", "recap-demo-18"]}]}'::jsonb,4,'2026-10-17T01:00:00+07:00','2026-10-17T01:00:00+07:00');
